'use client'

import { MorphingArea } from '@/components/spaceui/morphing-area'
import { getOptimizedImageUrl } from '@/lib/next-image-url'
import { imagelib } from '@/lib/imagelib'

export interface MorphingAreaDemoProps {
  corner?: number
  morph?: number
}

const imageSrc = getOptimizedImageUrl(imagelib.tools.imagesplit[0].url, { width: 552 })

export default function Demo({ corner = 18, morph = 50 }: MorphingAreaDemoProps) {
  return (
    <div className="flex flex-col items-center justify-center gap-[0.75rem] py-[1.5rem] px-[1rem]">
      <MorphingArea corner={Number(corner)} morph={Number(morph)} imageSrc={imageSrc} />
    </div>
  )
}
